function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 3 || grid.length > 100) return 'grid needs 3 to 100 rows.';
  const n = grid.length;
  if (grid.some(row => !Array.isArray(row) || row.length !== n)) return 'grid must be square: every row has n values.';
  if (grid.some(row => row.some(v => !Number.isInteger(v) || v < 1 || v > 100))) return 'Each value is an integer from 1 to 100.';
  return null;
}

