function largestLocal(grid) {
  const n = grid.length;
  const maxLocal = [];

  for (let i = 0; i < n - 2; i++) {
    const row = [];
    for (let j = 0; j < n - 2; j++) {
      let largest = 0;
      for (let r = i; r < i + 3; r++) {
        for (let c = j; c < j + 3; c++) {
          largest = Math.max(largest, grid[r][c]);
        }
      }
      row.push(largest);
    }
    maxLocal.push(row);
  }
  return maxLocal;
}

