function largestLocal(grid) {
  // Scatter instead of gather: every cell offers its value to each window that contains it.
  const size = grid.length - 2;
  const out = Array.from({ length: size }, () => new Array(size).fill(-Infinity));
  grid.forEach((cells, y) => cells.forEach((value, x) => {
    for (let top = y - 2; top <= y; top++) {
      for (let lft = x - 2; lft <= x; lft++) {
        if (top >= 0 && lft >= 0 && top < size && lft < size && value > out[top][lft]) out[top][lft] = value;
      }
    }
  }));
  return out;
}

