function generate(rand, size) {
  const n = size === 'large' ? 90 + Math.floor(rand() * 11) : 3 + Math.floor(rand() * 4);
  const top = rand() < 0.3 ? 1 + Math.floor(rand() * 3) : 100;
  const grid = Array.from({ length: n }, () => Array.from({ length: n }, () => 1 + Math.floor(rand() * top)));
  return [grid];
